#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Registers the production gateway in Claude Code and, when installed, Claude
# Desktop, authenticated with the GitHub token of a logged-in `gh` (LEDGER
# D59). Standalone: a colleague runs it without a clone of this repository.
#
#   curl -fsSLO https://raw.githubusercontent.com/bergbacher/hyde-mcp-gateway/main/scripts/wizard/client-setup.sh
#   bash client-setup.sh
#
# Both clients get the same stdio bridge: `bash -c` reads the token with
# `gh auth token` when the client starts, hands it to mcp-remote through its
# environment (never argv, never a file) and mcp-remote sends it as the
# Authorization header to the gateway. mcp-remote reads the header value
# from the literal `${AUTH_HEADER}`, which the bridge spells as `\$` +
# `{AUTH_HEADER}` so that Claude Code's own `${VAR}` expansion of a config
# never sees it. Claude Code cannot run a command for an HTTP header and
# Claude Desktop sends no custom header at all, so the bridge is what keeps
# the token off the disk in both. Re-runnable: each client holds one entry
# afterwards. Runbook: docs/runbooks/client-setup.md.

GATEWAY_URL="https://connextparb09d6769-hyde-mcp-gateway.functions.fnc.fr-par.scw.cloud/mcp"
SERVER=hyde-mcp-gateway
DESKTOP_DIR="$HOME/Library/Application Support/Claude"
DESKTOP_CONFIG="$DESKTOP_DIR/claude_desktop_config.json"
# HYDE_DESKTOP_APP: where the Desktop app is looked for; the tests point it elsewhere.
TOTAL_STAGES=6

die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

TMP="$(mktemp -d)"
chmod 700 "$TMP"
trap 'rm -rf "$TMP"' EXIT
trap 'exit 130' INT TERM HUP

# need TOOL HINT: TOOL on the PATH, or stop with HINT.
need() {
  command -v "$1" >/dev/null 2>&1 || die "$1 is not installed. $2"
  say "${GREEN}✓${RESET} $1: $(command -v "$1")"
}

# probe APP: POSTs a `ping` for APP to the gateway as the token; prints the
# HTTP status, leaves the body in $TMP/body. The token goes to curl through
# its config on stdin, not through argv. Stops on every status but 200,
# telling a rejected token (401) from a gateway that could not ask GitHub (503).
probe() {
  local code
  code="$(request "$1")" || die "curl failed: is the network up?"
  case "$code" in
    200) ;;
    401) die "this GitHub token is not accepted: GitHub rejected it. Run 'gh auth status' and 'gh auth refresh', then re-run." ;;
    503) die "the gateway could not reach GitHub to check the token; your token is fine. Try again in a minute." ;;
    *) die "the gateway answered HTTP $code for app $1: $(cat "$TMP/body")" ;;
  esac
}

request() {
  printf 'header = "Authorization: Bearer %s"\n' "$TOKEN" | curl -sS -K - -o "$TMP/body" -w '%{http_code}' \
    -X POST "$GATEWAY_URL" \
    -H 'Content-Type: application/json' -H 'Accept: application/json, text/event-stream' \
    -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"ping\",\"arguments\":{\"app\":\"$1\"}}}"
}

# tool_text JSON: the `text` of a tool result, unescaped.
tool_text() {
  printf '%s' "$1" | sed -nE 's/.*"text":"(([^"\\]|\\.)*)".*/\1/p' | sed 's/\\"/"/g'
}

# body_text: the tool text of the answer in $TMP/body (SSE or plain JSON).
body_text() {
  local json
  json="$(sed -n 's/^data: //p' "$TMP/body" | head -n1)"
  [[ -n "$json" ]] || json="$(cat "$TMP/body")"
  tool_text "$json"
}

# scope_of PING_JSON: the apps a ping result grants, space-separated; `*` as every registered app.
scope_of() {
  local scope
  scope="$(printf '%s' "$1" | sed -n 's/.*"scope":\(.*\)}$/\1/p')"
  if [[ "$scope" == '"*"' ]]; then printf '%s' "${REGISTERED[*]}"; return; fi
  printf '%s' "$scope" | tr -d '[]"' | tr ',' ' '
}

# JSON-RPC lines for one ping through the bridge.
rpc_ping() {
  printf '%s\n' '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"client-setup","version":"0"}}}'
  printf '%s\n' '{"jsonrpc":"2.0","method":"notifications/initialized"}'
  printf '{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"ping","arguments":{"app":"%s"}}}\n' "$1"
}

# ── Stages ────────────────────────────────────────────────────────────────

banner "$SERVER in Claude Code and Claude Desktop"

stage "Prerequisites"
say "The gateway is read through your own GitHub login; nothing is issued to you."
need gh "Install it: brew install gh"
need claude "Install Claude Code: curl -fsSL https://claude.ai/install.sh | bash"
need node "Install it: brew install node (the bridge runs mcp-remote through npx)"
need npx "Install it: brew install node"
DESKTOP=0
if [[ -d "$DESKTOP_DIR" || -d "${HYDE_DESKTOP_APP:-/Applications/Claude.app}" ]]; then
  DESKTOP=1; say "${GREEN}✓${RESET} Claude Desktop: $DESKTOP_CONFIG"
else
  note "Claude Desktop is not installed; only Claude Code is configured."
fi
# The clients start the bridge with their own PATH, so it names the directories.
BRIDGE="export PATH=\"$(dirname "$(command -v node)"):$(dirname "$(command -v gh)"):\$PATH\" AUTH_HEADER=\"Bearer \$(gh auth token)\"; exec npx -y mcp-remote \"$GATEWAY_URL\" --transport http-only --header \"Authorization:\\\$\"'{AUTH_HEADER}'"
pause "Continue?"

stage "GitHub login"
if gh auth status -h github.com >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} gh is logged in to github.com; its token is the gateway credential."
else
  say "gh is not logged in. The login opens in your browser; finish it there."
  gh auth login -h github.com -w || die "gh auth login failed; run it by hand, then re-run"
  gh auth status -h github.com >/dev/null 2>&1 || die "gh is still not logged in"
  say "${GREEN}✓${RESET} logged in"
fi
TOKEN="$(gh auth token)" || die "gh auth token failed"
[[ -n "$TOKEN" ]] || die "gh auth token printed nothing"
pause

stage "Token check against the gateway"
say "One authenticated ping to $GATEWAY_URL"
probe -
text="$(body_text)"
[[ "$text" == "unknown app -; registered: "* ]] || die "unexpected answer from the gateway: $text"
REGISTERED=()
for app in ${text#*registered: }; do REGISTERED+=("${app%,}"); done
((${#REGISTERED[@]})) || die "the gateway registers no app"
say "${GREEN}✓${RESET} token accepted; registered apps: ${REGISTERED[*]}"
# The scope comes from a ping inside it: the first app this token may read answers with the whole scope.
SCOPE=""
for app in "${REGISTERED[@]}"; do
  probe "$app"
  text="$(body_text)"
  if [[ "$text" == "{"* ]]; then SCOPE="$(scope_of "$text")"; break; fi
  [[ "$text" == *"is not authorized for app"* ]] || die "unexpected answer for $app: $text"
done
if [[ -n "$SCOPE" ]]; then
  say "${GREEN}✓${RESET} apps in scope: $SCOPE"
else
  warn "this token reads none of the app repositories, so its scope is empty."
  say "Ask for read access to the app repositories you need; the gateway needs no change."
  say "The registration below works as soon as the access exists."
fi
pause

stage "Claude Code"
say "Registers $SERVER at user scope, so every project sees it:"
note "$ claude mcp add -s user $SERVER -- /bin/bash -c '<bridge>'"
note "<bridge> = $BRIDGE"
claude mcp remove -s user "$SERVER" >/dev/null 2>&1 || true
claude mcp add -s user "$SERVER" -- /bin/bash -c "$BRIDGE" >/dev/null || die "claude mcp add failed"
say "${GREEN}✓${RESET} registered; /mcp in Claude Code lists it"
pause

stage "Claude Desktop"
if (( DESKTOP )); then
  say "Writes the same bridge to ${DESKTOP_CONFIG/#$HOME/~}, replacing an existing $SERVER entry."
  mkdir -p "$DESKTOP_DIR"   # absent until Desktop's first start
  node -e '
    const fs = require("node:fs");
    const [file, name, command, ...args] = process.argv.slice(1);
    let config = {};
    if (fs.existsSync(file)) {
      const raw = fs.readFileSync(file, "utf8");
      if (raw.trim()) config = JSON.parse(raw);
    }
    config.mcpServers = { ...(config.mcpServers ?? {}), [name]: { command, args } };
    fs.writeFileSync(file, JSON.stringify(config, null, 2) + "\n");
  ' "$DESKTOP_CONFIG" "$SERVER" /bin/bash -c "$BRIDGE" || die "could not update $DESKTOP_CONFIG; is it valid JSON?"
  say "${GREEN}✓${RESET} written"
  warn "Quit Claude Desktop and open it again: it reads the config at start."
  SKIPPED+=("restart Claude Desktop, then look for $SERVER's tools")
else
  note "Claude Desktop is not installed; skipped."
fi
pause

stage "Ping through the configured server"
say "Claude Code's view of the entry:"
claude mcp get "$SERVER" | sed 's/^/    /' || die "Claude Code does not list $SERVER"
app="${SCOPE%% *}"; [[ -n "$app" ]] || app="${REGISTERED[0]}"
say "Starts the bridge as the clients do and calls ping for $app (the first run downloads mcp-remote):"
mkfifo "$TMP/in"
/bin/bash -c "$BRIDGE" <"$TMP/in" >"$TMP/out" 2>"$TMP/err" &
bridge_pid=$!
exec 3>"$TMP/in"
# A bridge that died already closes the pipe; the write fails and the wait below reports why.
rpc_ping "$app" >&3 2>/dev/null || true
for _ in $(seq 1 360); do grep -q '"id":2' "$TMP/out" 2>/dev/null && break; sleep 0.5; done
exec 3>&-
# npx runs mcp-remote as a child; end both.
pkill -P "$bridge_pid" 2>/dev/null || true
kill "$bridge_pid" 2>/dev/null || true
wait "$bridge_pid" 2>/dev/null || true
answer="$(grep '"id":2' "$TMP/out" || true)"
[[ -n "$answer" ]] || die "the bridge gave no answer within 3 minutes: $(tail -n 3 "$TMP/err")"
text="$(tool_text "$answer")"
if [[ "$text" == "{"* ]]; then
  say "${GREEN}✓${RESET} ping answered; scope: $(scope_of "$text")"
elif [[ "$text" == *"is not authorized for app"* ]]; then
  say "${GREEN}✓${RESET} ping answered through the bridge; scope: none (ask for read access to the app repositories)"
else
  die "ping failed: $text"
fi
pause

finish
note "Claude Code: /mcp lists $SERVER; ask it to call ping with an app in scope."
